func TestManagedWorkerMatchingJournalAlwaysRollsBack(t *testing.T) {
	for _, confirmed := range []bool{false, true} {
		t.Run(map[bool]string{false: "pending", true: "confirmed"}[confirmed], func(t *testing.T) {
