func (e enroller) enroll(ctx context.Context, cfg Config) (result error) {
	cfg, err := cfg.normalized()
	if err != nil {
		return err
	}
	ctx, cancel := context.WithTimeout(ctx, enrollmentLimit)
	defer cancel()
	lock, err := lockRuntime(e.runtimePath)
	if err != nil {
		return err
	}
	defer lock.Close()
	if err := removeSetupKey(e.runtimePath); err != nil {
		return err
	}
	if err := updateHosts(e.hostsPath, cfg.ManagementIP); err != nil {
		return err
	}
	current, err := e.awaitDaemon(ctx)
	if err != nil {
		return err
	}
	if current.managerMatches(cfg.ManagementURL) && current.DaemonStatus == "Connecting" {
		// At boot the daemon is already reconnecting its saved identity. A
		// second up cannot speed that up; let it settle before deciding.
		current, _, err = e.observe(ctx, e.pending, nil, func(status daemonStatus) bool {
			return status.DaemonStatus != "Connecting"
		})
		if err != nil {
			return err
		}
	}
	managerMatches := current.managerMatches(cfg.ManagementURL)
	reapply := false
	if managerMatches && current.DaemonStatus == "Connected" {
		applied, err := e.settingsApplied(ctx, cfg.ManagementURL)
		if err != nil {
			return err
		}
		if applied && current.ready(cfg.ManagementURL) {
			return nil
		}
		reapply = !applied
	}
	// NetBird names a peer only when it first registers; later logins with the
	// saved identity keep the manager's name. Resolve it before any down.
	name, err := e.peerName(ctx, cfg)
	if err != nil {
		return err
	}
	if reapply {
		// NetBird's up command returns early while already connected. Bring
		// the saved identity down once to apply the server settings.
		if _, err := e.command(ctx, "down"); err != nil {
			return errors.New("cannot apply TerraScale NetBird server settings")
		}
	}
	args := append([]string{"up", "--config", netbirdConfig, "--management-url", cfg.ManagementURL,
		"--hostname", name, "--no-browser"}, upSettings()...)
	if managerMatches && !current.needsLogin() {
		// Login with the saved WireGuard identity first. A network outage must
		// not consume a new setup key or replace an existing registration.
		_, upErr := e.command(ctx, args...)
		current, err = e.status(ctx)
		if err != nil {
			return err
		}
		if !current.needsLogin() {
			if upErr != nil && !current.Management.Connected {
				return errors.New("NetBird could not reconnect its saved identity")
			}
			return e.waitReady(ctx, cfg.ManagementURL, &current)
		}
	}
	key, err := e.readKey(ctx, cfg)
	if err != nil {
		clear(key)
		return errors.New("cannot retrieve NetBird setup key from OCI Vault")
	}
	defer clear(key)
	if !validSetupKey(key) {
		return errors.New("OCI Vault returned an invalid NetBird setup key")
	}
	path, err := writeSetupKey(e.runtimePath, key)
	if err != nil {
		return err
	}
	clear(key)
	defer func() {
		if err := removeSetupKey(e.runtimePath); err != nil {
			result = errors.Join(result, err)
		}
	}()
	if !managerMatches && current.Management.URL != "" && current.engineActive() {
		if _, err := e.command(ctx, "down"); err != nil {
			return errors.New("cannot disconnect NetBird from its previous manager")
		}
	}
	if _, err := e.command(ctx, append(args, "--setup-key-file", path)...); err != nil {
		return errors.New("NetBird setup-key enrollment failed")
	}
	return e.waitReady(ctx, cfg.ManagementURL, nil)
}

func (status daemonStatus) managerMatches(manager string) bool {
	configured, err := normalizeManagerURL(status.Management.URL)
	return err == nil && configured == manager
}

func (status daemonStatus) ready(manager string) bool {
	return status.DaemonStatus == "Connected" && status.managerMatches(manager) && status.Management.Connected && status.Signal.Connected
}

func (status daemonStatus) needsLogin() bool {
	// NetBird also uses LoginFailed for network/IO errors. Only an explicit
	// authentication state warrants consuming a fresh setup key.
	return status.DaemonStatus == "NeedsLogin" || status.DaemonStatus == "SessionExpired"
}

// engineActive reports whether the daemon may hold a running or retrying
// client. A fresh daemon (NeedsLogin: v0.79 does not connect a just-created
// configuration) or a stopped one (Idle) has nothing to bring down, so the
// first enrollment skips the extra down.
func (status daemonStatus) engineActive() bool {
	return status.DaemonStatus != "NeedsLogin" && status.DaemonStatus != "Idle"
}

func (e enroller) awaitDaemon(ctx context.Context) (daemonStatus, error) {
	waitCtx, cancel := context.WithTimeout(ctx, daemonLimit)
	defer cancel()
	delay := e.poll
	for {
		if e.socketReady() {
			status, err := e.status(waitCtx)
			if !errors.Is(err, errDaemonUnreachable) {
				return status, err
			}
		}
		select {
		case <-waitCtx.Done():
			if err := ctx.Err(); err != nil {
				return daemonStatus{}, err
			}
			return daemonStatus{}, errDaemonUnreachable
		case <-time.After(delay):
		}
		delay = min(2*delay, maxPoll)
	}
}

func (e enroller) socketReady() bool {
	if e.socketPath == "" {
		return true
	}
	info, err := os.Lstat(e.socketPath)
	return err == nil && info.Mode().Type() == os.ModeSocket
}

func (e enroller) status(ctx context.Context) (daemonStatus, error) {
	wire, err := e.command(ctx, "status", "--json", "--config", netbirdConfig)
	if err != nil {
		return daemonStatus{}, errDaemonUnreachable
	}
	defer clear(wire)
	var status daemonStatus
	if len(wire) > 1<<20 || json.Unmarshal(wire, &status) != nil {
		return daemonStatus{}, errors.New("NetBird daemon returned invalid status JSON")
	}
	switch status.DaemonStatus {
	case "Idle", "Connecting", "Connected", "NeedsLogin", "LoginFailed", "SessionExpired":
		return status, nil
	default:
		return daemonStatus{}, errors.New("NetBird daemon returned an unknown connection state")
	}
}

func (e enroller) waitReady(ctx context.Context, manager string, first *daemonStatus) error {
	status, done, err := e.observe(ctx, readyLimit, first, func(status daemonStatus) bool {
		return status.ready(manager) || status.needsLogin()
	})
	if err != nil {
		return err
	}
	if !done {
		return errors.New("NetBird management and signal connectivity did not become ready")
	}
	if status.needsLogin() {
		return errors.New("NetBird enrollment still requires authentication")
	}
	applied, err := e.settingsApplied(ctx, manager)
	if err != nil {
		return err
	}
	if !applied {
		return errors.New("NetBird server settings were not applied")
	}
	return nil
}

// observe polls daemon status with exponential backoff from e.poll to maxPoll
// until done holds or limit elapses, and returns the last observation; a
// cancelled ctx returns its error, the elapsed limit does not. Each
// poll forks the NetBird CLI once, so the backoff keeps a slow connect cheap
// while a fast one is seen within e.poll.
func (e enroller) observe(ctx context.Context, limit time.Duration, first *daemonStatus, done func(daemonStatus) bool) (daemonStatus, bool, error) {
	deadline := time.Now().Add(limit)
	// Every status query is bounded by the limit too: the CLI's own command
	// timeout is far longer, and a poll started near the limit must not run
	// past it and consume the budget of later enrollment steps.
	limited, cancel := context.WithDeadline(ctx, deadline)
	defer cancel()
	delay := e.poll
	var last daemonStatus
	observed := false
	for {
		var status daemonStatus
		if first != nil {
			status, first = *first, nil
		} else {
			var err error
			if status, err = e.status(limited); err != nil {
				// A query cut short by cancellation reports the cancellation,
				// not an unreachable daemon.
				if ctxErr := ctx.Err(); ctxErr != nil {
					return daemonStatus{}, false, ctxErr
				}
				// A query cut short by the limit is the limit elapsing. With
				// no observation yet there is nothing to report: a zero
				// status would read as a daemon bound to no manager.
				if limited.Err() != nil {
					if !observed {
						return daemonStatus{}, false, errors.Join(errors.New("NetBird status did not answer within its observation limit"), err)
					}
					return last, false, nil
				}
				return daemonStatus{}, false, err
			}
		}
		last, observed = status, true
		if done(status) {
			return status, true, nil
		}
		remaining := time.Until(deadline)
		if remaining <= 0 {
			return status, false, nil
		}
		select {
		case <-ctx.Done():
			// Cancellation is not the limit elapsing: report its cause so
			// callers do not keep acting on a stale observation.
			return status, false, ctx.Err()
		case <-time.After(min(delay, remaining)):
		}
		delay = min(2*delay, maxPoll)
	}
}

// settingsApplied reports whether the daemon's effective configuration
// matches the same serverSettings used to construct the enrollment flags.
func (e enroller) settingsApplied(ctx context.Context, manager string) (bool, error) {
	wire, err := e.command(ctx, "debug", "config")
	if err != nil {
		return false, errors.New("cannot query effective NetBird configuration")
	}
	defer clear(wire)
	var cfg map[string]jsontext.Value
	if len(wire) > 1<<20 || json.Unmarshal(wire, &cfg) != nil {
		return false, errors.New("NetBird daemon returned invalid effective configuration")
	}
	applied := true
	for _, setting := range serverSettings {
		var value *bool
		if json.Unmarshal(cfg[setting.key], &value) != nil || value == nil {
			return false, errors.New("NetBird daemon returned invalid effective configuration")
		}
		applied = applied && *value == setting.want
	}
	var managementURL string
	if json.Unmarshal(cfg["managementUrl"], &managementURL) != nil {
		return false, errors.New("NetBird daemon returned invalid effective configuration")
	}
	configuredManager, err := normalizeManagerURL(managementURL)
	return applied && err == nil && configuredManager == manager, nil
}

func (e enroller) command(ctx context.Context, args ...string) ([]byte, error) {
	commandCtx, cancel := context.WithTimeout(ctx, commandLimit)
	defer cancel()
	wire, err := e.run(commandCtx, netbirdBinary, append(args,
		"--daemon-addr", "unix:///var/run/netbird.sock", "--log-file", "console", "--log-level", "error")...)
	if args[0] != "status" && !(args[0] == "debug" && args[1] == "config") || err != nil {
		clear(wire)
		return nil, err
	}
	return wire, nil
}

func lockRuntime(directory string) (*os.File, error) {
	if err := os.Mkdir(directory, 0o700); err != nil && !errors.Is(err, os.ErrExist) {
		return nil, errors.New("cannot create NetBird enrollment runtime directory")
	}
	info, err := os.Lstat(directory)
	if err != nil || !info.IsDir() || info.Mode().Perm() != 0o700 {
		return nil, errors.New("NetBird runtime directory must be a root-only directory")
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || stat.Uid != uint32(os.Geteuid()) {
		return nil, errors.New("NetBird runtime directory has an unexpected owner")
	}
	fd, err := syscall.Open(filepath.Join(directory, "enroll.lock"), syscall.O_RDWR|syscall.O_CREAT|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0o600)
	if err != nil {
		return nil, errors.New("cannot open NetBird enrollment lock")
	}
	lock := os.NewFile(uintptr(fd), "enroll.lock")
	info, err = lock.Stat()
	if err != nil || !ownedRegular(info, 0o077) {
		lock.Close()
		return nil, errors.New("NetBird enrollment lock must be root-only")
	}
	if err := syscall.Flock(fd, syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		lock.Close()
		return nil, errors.New("another NetBird enrollment is running")
	}
	return lock, nil
}

func removeSetupKey(directory string) error {
	path := filepath.Join(directory, "setup-key")
	info, err := os.Lstat(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil || !ownedRegular(info, 0o077) {
		return errors.New("unsafe leftover NetBird setup-key file")
	}
	if err := os.Remove(path); err != nil {
		return errors.New("cannot remove transient NetBird setup-key file")
	}
	return nil
}

func hostsContent(original []byte, ip string) ([]byte, error) {
	var updated strings.Builder
	seenManaged := false
	for line := range strings.SplitSeq(string(original), "\n") {
		// Only the exact one-host entry bearing our marker is owned by us.
		addressPart, comment, _ := strings.Cut(line, "#")
		fields := strings.Fields(addressPart)
		managed := "#"+strings.TrimRight(comment, " \t\r") == hostsMarker
		if managed {
			if seenManaged || len(fields) != 2 || fields[1] != managerHostname {
				return nil, errors.New("unexpected NetBird managed hosts entry")
			}
			seenManaged = true
			continue
		}
		if len(fields) > 1 {
			for _, hostname := range fields[1:] {
				if strings.EqualFold(hostname, managerHostname) {
					return nil, errors.New("an unmanaged hosts entry already defines the NetBird manager")
				}
			}
		}
		updated.WriteString(line)
		updated.WriteByte('\n')
	}
	result := strings.TrimSuffix(updated.String(), "\n")
	if ip != "" {
		if result != "" && !strings.HasSuffix(result, "\n") {
			result += "\n"
		}
		result += ip + "\t" + managerHostname + "\t" + hostsMarker + "\n"
	}
	return []byte(result), nil
}

func readHosts(path string) ([]byte, os.FileInfo, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, nil, errors.New("cannot open hosts file for NetBird manager resolution")
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !ownedRegular(info, 0o022) || info.Size() > 1<<20 {
		return nil, nil, errors.New("hosts file must be a root-owned bounded regular file")
	}
	body, err := io.ReadAll(io.LimitReader(file, 1<<20+1))
	if err != nil || len(body) > 1<<20 {
		return nil, nil, errors.New("cannot read bounded hosts file")
	}
	return body, info, nil
}

func updateHosts(path, ip string) error {
	original, info, err := readHosts(path)
	if err != nil {
		return err
	}
	body, err := hostsContent(original, ip)
	if err != nil || bytes.Equal(body, original) {
		return err
	}
	directory := filepath.Dir(path)
	temporary, err := os.CreateTemp(directory, ".terrascale-netbird-hosts-*")
	if err != nil {
		return errors.New("cannot create atomic NetBird hosts update")
	}
	defer os.Remove(temporary.Name())
	defer temporary.Close()
	stat := info.Sys().(*syscall.Stat_t)
	if err := temporary.Chmod(info.Mode().Perm()); err != nil {
		return errors.New("cannot preserve hosts file mode")
	}
	if err := temporary.Chown(int(stat.Uid), int(stat.Gid)); err != nil {
		return errors.New("cannot preserve hosts file ownership")
	}
	if _, err := temporary.Write(body); err != nil {
		return errors.New("cannot write atomic NetBird hosts update")
	}
	if err := temporary.Sync(); err != nil {
		return errors.New("cannot sync atomic NetBird hosts update")
	}
	if err := temporary.Close(); err != nil {
		return errors.New("cannot close atomic NetBird hosts update")
	}
	current, currentInfo, err := readHosts(path)
	if err != nil || !os.SameFile(info, currentInfo) || !bytes.Equal(current, original) {
		return errors.New("hosts file changed during NetBird manager update")
	}
	if err := os.Rename(temporary.Name(), path); err != nil {
		return errors.New("cannot atomically install NetBird hosts update")
	}
	parent, err := os.Open(directory)
	if err != nil {
		return errors.New("cannot sync hosts directory")
	}
	defer parent.Close()
	if err := parent.Sync(); err != nil {
		return errors.New("cannot sync hosts directory")
	}
	return nil
}

func (e enroller) peerName(ctx context.Context, cfg Config) (string, error) {
	if len(cfg.PeerNames) > 0 {
		ip, err := e.primaryIP(ctx)
		if err != nil {
			return "", errors.New("cannot read the server's primary private IPv4 address from OCI instance metadata")
		}
		if name, ok := cfg.PeerNames[ip.String()]; ok {
			return name, nil
		}
	}
	hostname, err := e.hostname()
	if err != nil || hostname == "" || len(hostname) > 253 || strings.ContainsAny(hostname, "\x00\r\n\t ") {
		return "", errors.New("cannot determine a valid server hostname for NetBird")
	}
	return hostname, nil
}

func recordEnrollment(ctx context.Context, cfg Config, hostname func() (string, error), result error) {
	name := "this host"
	if hostname != nil {
		if host, err := hostname(); err == nil && host != "" {
			name = host
		}
	}
	decision := decisionlog.Decision{
		Region:  cfg.Region,
		Actor:   decisionlog.Actor{Slice: "netbird"},
		Kind:    decisionlog.KindPeerEnrolled,
		Subject: decisionlog.Subject{Kind: "peer", ID: name},
		Rule:    "NetBird private overlay enrollment",
		Attrs:   map[string]string{"management_url": cfg.ManagementURL},
	}
	if result != nil {
		decision.Status = decisionlog.StatusFailed
		decision.Summary = "NetBird enrollment of " + name + " failed"
		// Enrollment also fails before connecting (runtime lock, hosts
		// file, Vault, settings) and in setup-key cleanup after connecting,
		// so the failure does not say the peer is disconnected.
		decision.Reason = "The enrollment did not complete; the failure may be in preparation, connectivity or setup-key cleanup."
		decision.Outcome = "enrollment failed"
	} else {
		decision.Status = decisionlog.StatusSucceeded
		decision.Summary = "NetBird peer " + name + " enrolled"
		decision.Reason = "The peer connected to TerraScale management and signal with the reviewed settings."
		decision.Outcome = "connected"
	}
	decisionlog.Record(ctx, decision)
}

func SetDefault(recorder Recorder) (restore func()) {
	var holder *recorderHolder
	if recorder != nil {
		holder = &recorderHolder{recorder: recorder}
	}
	previous := defaultRecorder.Swap(holder)
	return func() { defaultRecorder.CompareAndSwap(holder, previous) }
}

// Default returns the installed recorder, or nil when records go to the log.
func Default() Recorder {
	if holder := defaultRecorder.Load(); holder != nil {
		return holder.recorder
	}
	return nil
}

// Record journals one decision with the process-wide recorder and returns
// its ID, so a caller can link later decisions to it with ParentID. It never
// blocks on the network and never fails; see the package documentation.
func Record(ctx context.Context, decision Decision) string {
	if recorder := Default(); recorder != nil {
		return recorder.Record(ctx, decision)
	}
	return LogRecorder{}.Record(ctx, decision)
}

func NewJournal(config JournalConfig) *Journal {
	if config.QueueSize <= 0 {
		config.QueueSize = DefaultQueueSize
	}
	if config.Capacity <= 0 {
		config.Capacity = DefaultCapacity
	}
	if config.PublishTimeout <= 0 {
		config.PublishTimeout = DefaultPublishTimeout
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	journal := &Journal{config: config, queue: make(chan Decision, config.QueueSize),
		ring: make([]Decision, config.Capacity), ids: map[string]bool{},
		subscribers: map[*subscriber]struct{}{}}
	journal.Attach(config.Sink, config.Archive)
	return journal
}

// Attach sets the durable sink and archive. Decisions recorded before a sink
// is attached stay queued (up to the queue bound) and are published once it
// is.
func (journal *Journal) Attach(sink Sink, archive Archive) {
	if sink == nil && archive == nil {
		return
	}
	journal.storage.Store(&storageHolder{sink: sink, archive: archive})
}

func (journal *Journal) currentStorage() (Sink, Archive) {
	if holder := journal.storage.Load(); holder != nil {
		return holder.sink, holder.archive
	}
	return nil, nil
}

// Record indexes the decision, queues it for publishing and returns its ID.
// A full queue drops the durable copy and counts it; the in-memory copy and
// the log line are kept.
func (journal *Journal) Record(ctx context.Context, decision Decision) string {
	if decision.Region == "" {
		decision.Region = journal.config.Region
	}
	if decision.Actor.Member == "" {
		decision.Actor.Member = journal.config.Member
	}
	decision = decision.Normalize(journal.config.Now())
	// A decision with a caller-chosen ID that is already indexed (an
	// idempotent replay) is indexed and logged once. Its durable copy is
	// queued again unless it is known to be stored, since the first attempt
	// may have been dropped from a full queue or failed to publish; the
	// stream deduplicates a copy that did land by its message ID.
	if fresh, durable := journal.ingest(decision, false); !fresh {
		if !durable {
			journal.enqueue(decision)
		}
		return decision.ID
	}
	journal.recorded.Add(1)
	recordedTotal.Inc()
	if journal.config.Log {
		LogRecorder{}.Record(ctx, decision)
	}
	journal.enqueue(decision)
	return decision.ID
}

func (journal *Journal) enqueue(decision Decision) {
	select {
	case journal.queue <- decision:
		queueDepth.Add(1)
	default:
		journal.dropped.Add(1)
		droppedQueueFull.Inc()
	}
}

func (journal *Journal) ingest(decision Decision, durable bool) (bool, bool) {
	journal.mu.Lock()
	defer journal.mu.Unlock()
	if known, seen := journal.ids[decision.ID]; seen {
		if durable && !known {
			journal.ids[decision.ID] = true
		}
		return false, known || durable
	}
	ingestedTotal.Inc()
	capacity := len(journal.ring)
	if journal.size == capacity {
		evicted := journal.ring[journal.start]
		delete(journal.ids, evicted.ID)
		if evicted.Time.After(journal.coveredFrom) {
			journal.coveredFrom = evicted.Time
		}
		journal.ring[journal.start] = decision
		journal.start = (journal.start + 1) % capacity
	} else {
		journal.ring[(journal.start+journal.size)%capacity] = decision
		journal.size++
	}
	journal.ids[decision.ID] = durable
	for subscriber := range journal.subscribers {
		select {
		case subscriber.decisions <- decision:
		default:
		}
	}
	return true, durable
}

func (journal *Journal) snapshot() ([]Decision, time.Time) {
	journal.mu.RLock()
	defer journal.mu.RUnlock()
	decisions := make([]Decision, 0, journal.size)
	for offset := range journal.size {
		decisions = append(decisions, journal.ring[(journal.start+offset)%len(journal.ring)])
	}
	return decisions, journal.coveredFrom
}

// Query returns matching decisions newest first. A range older than the
// in-memory window is read from the archive when one is attached, and
// reported Partial otherwise.
func (journal *Journal) Query(ctx context.Context, query Query) (Result, error) {
	query = query.Normalized()
	// The replay flag is read before the snapshot: a replay that ends in
	// between leaves the result conservatively partial, never the reverse.
	replaying := journal.replaying.Load()
	decisions, coveredFrom := journal.snapshot()
	result := Result{}
	seen := make(map[string]struct{}, len(decisions))
	// fresh counts matches newer than coveredFrom. Memory evicts by arrival,
	// not by time, so only those are known to outrank everything evicted.
	fresh := 0
	for _, decision := range decisions {
		if query.Matches(decision) {
			result.Decisions = append(result.Decisions, decision)
			seen[decision.ID] = struct{}{}
			if decision.Time.After(coveredFrom) {
				fresh++
			}
		}
	}
	// While the stream tail is still replaying, memory does not hold the
	// region's history yet.
	if replaying {
		result.Partial = true
	}
	// Older decisions only matter when memory did not fill the page with
	// decisions newer than anything it evicted.
	older := !coveredFrom.IsZero() && (query.Since.IsZero() || query.Since.Before(coveredFrom))
	exhausted := !older
	if older && fresh < query.Limit {
		_, archive := journal.currentStorage()
		if archive == nil {
			result.Partial = true
		} else if complete, reachedFloor := journal.scanArchive(ctx, archive, query, coveredFrom, seen, &result); !complete {
			result.Partial = true
		} else {
			exhausted = reachedFloor
		}
	}
	SortNewestFirst(result.Decisions)
	switch {
	case len(result.Decisions) > query.Limit:
		result.Decisions = result.Decisions[:query.Limit]
		result.Truncated = true
	case len(result.Decisions) == query.Limit && !exhausted:
		// A full page with older history left unsearched may not be all:
		// say so rather than look exhaustive.
		result.Truncated = true
	}
	return result, nil
}

func (query Query) Normalized() Query {
	if query.Limit <= 0 {
		query.Limit = DefaultQueryLimit
	}
	query.Limit = min(query.Limit, MaxQueryLimit)
	query.Regions = slices.Clone(query.Regions)
	for index, region := range query.Regions {
		query.Regions[index] = strings.ToLower(region)
	}
	query.Subject = strings.ToLower(query.Subject)
	return query
}

// Matches reports whether a decision satisfies every filter of a normalized
// query.
func (query Query) Matches(decision Decision) bool {
	if len(query.Regions) > 0 && !slices.Contains(query.Regions, decision.Region) {
		return false
	}
	if len(query.Kinds) > 0 && !slices.Contains(query.Kinds, decision.Kind) {
		return false
	}
	if len(query.Actors) > 0 && !slices.ContainsFunc(query.Actors, func(actor string) bool {
		return actor == decision.Actor.Slice || actor == decision.Actor.Slice+"/"+decision.Actor.Member
	}) {
		return false
	}
	if query.SubjectKind != "" && query.SubjectKind != decision.Subject.Kind {
		return false
	}
	if query.SubjectID != "" && query.SubjectID != decision.Subject.ID {
		return false
	}
	if query.Subject != "" && !containsFold(decision.Subject.ID, query.Subject) &&
		!containsFold(decision.Subject.Name, query.Subject) && !containsFold(decision.Summary, query.Subject) {
		return false
	}
	if len(query.Statuses) > 0 && !slices.Contains(query.Statuses, decision.Status) {
		return false
	}
	if query.ParentID != "" && query.ParentID != decision.ParentID {
		return false
	}
	if !query.Since.IsZero() && decision.Time.Before(query.Since) {
		return false
	}
	if !query.Until.IsZero() && !decision.Time.Before(query.Until) {
		return false
	}
	return true
}
